<?php $categories=query('SELECT * FROM categories ORDER BY name')->fetchAll(); $suppliers=query('SELECT * FROM suppliers ORDER BY name')->fetchAll(); ?>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="inventory"><?php field('q','Search item',$_GET['q']??'','search',false); selectField('category','Category',$categories,$_GET['category']??'',true); field('location','Location',$_GET['location']??'','text',false); endForm('Search'); ?>
<?php $sql='SELECT i.*,c.name category FROM items i JOIN categories c ON c.id=i.category_id WHERE i.name LIKE ? AND i.location LIKE ?'; $params=['%'.($_GET['q']??'').'%','%'.($_GET['location']??'').'%']; if(!empty($_GET['category'])) { $sql.=' AND i.category_id=?'; $params[]=(int)$_GET['category']; } $rows=query($sql.' ORDER BY i.name',$params)->fetchAll(); ?>
<div class="table-wrap"><table><tr><th>Item</th><th>Category</th><th>Available</th><th>Condition</th><th>Location</th><?php if(manager()): ?><th>Actions</th><?php endif ?></tr><?php foreach($rows as $r): ?><tr><td><b><?= e($r['name']) ?></b></td><td><?= e($r['category']) ?></td><td><span class="badge <?= $r['quantity']<=$r['low_stock']?'warn':'' ?>"><?= e($r['quantity'].' '.$r['unit']) ?></span></td><td><?= e($r['item_condition']) ?></td><td><?= e($r['location']) ?></td><?php if(manager()): ?><td class="actions"><a href="?page=inventory&edit=<?= $r['id'] ?>">Edit</a><?php deleteForm('delete_item',$r['id']); ?></td><?php endif ?></tr><?php endforeach ?></table></div><?php if(!$rows): ?><p class="empty">No items found. Add your first inventory item below.</p><?php endif ?></section>
<?php if(manager()): $item=!empty($_GET['edit'])?query('SELECT * FROM items WHERE id=?',[(int)$_GET['edit']])->fetch():[]; $item=$item?:[]; ?><section class="panel"><h2><?= $item?'Edit item':'Add inventory item' ?></h2><p>Quantity is stock currently available to borrow. Borrowed units are tracked separately.</p><?php startForm('save_item',$item['id']??0); ?><div class="form-grid"><?php field('name','Item name',$item['name']??''); selectField('category_id','Category',$categories,$item['category_id']??''); selectField('supplier_id','Supplier',$suppliers,$item['supplier_id']??'',true); field('quantity','Available quantity',$item['quantity']??0,'number'); field('unit','Unit (pieces, boxes…)',$item['unit']??'pieces'); field('item_condition','Condition',$item['item_condition']??'Good'); field('location','Location',$item['location']??''); field('low_stock','Low-stock threshold',$item['low_stock']??5,'number'); ?></div><?php endForm($item?'Update item':'Add item'); ?></section><?php endif ?>
